"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Input, type InputProps } from "@/components/ui/input"
import { Textarea, type TextareaProps } from "@/components/ui/textarea"
import { Checkbox, type CheckboxProps } from "@/components/ui/checkbox"

/* ------------------------------------------------------------------ */
/* TextField — deprecated alias of Input (label, helper, error,         */
/* leading, trailing now live on Input). Figma: ❖ Input / Text Input    */
/* Field (152:7398)                                                    */
/* ------------------------------------------------------------------ */

/** @deprecated Use `InputProps`. */
type TextFieldProps = InputProps

/** @deprecated Use `Input` with the same props (`label`, `helper`, `error`, `leading`, `trailing`…). */
function TextField(props: TextFieldProps) {
  // wrapperClassName is always passed, so the alias renders the field wrapper even without a label.
  return <Input {...props} wrapperClassName={props.wrapperClassName} />
}

/* ------------------------------------------------------------------ */
/* PasswordField — deprecated alias: Input with the reveal button        */
/* ------------------------------------------------------------------ */

/** @deprecated Use `Input` with `type="password"` and `revealable`. */
function PasswordField(props: TextFieldProps) {
  return <Input autoComplete="current-password" {...props} type="password" revealable wrapperClassName={props.wrapperClassName} />
}

/* ------------------------------------------------------------------ */
/* TextareaField — deprecated alias of Textarea (label, helper, error,   */
/* optional and wrapperClassName now live on Textarea)                   */
/* ------------------------------------------------------------------ */

/** @deprecated Use `TextareaProps`. */
type TextareaFieldProps = TextareaProps

/** @deprecated Use `Textarea` with the same props (`label`, `helper`, `error`, `optional`…). */
function TextareaField(props: TextareaFieldProps) {
  // wrapperClassName is always passed, so the alias renders the field wrapper even without a label.
  return <Textarea {...props} wrapperClassName={props.wrapperClassName} />
}

/* ------------------------------------------------------------------ */
/* CheckboxField — deprecated alias of Checkbox (label, description,     */
/* error now live on Checkbox). Figma: ❖ Selectors / Checkbox Item       */
/* (113:7985)                                                          */
/* ------------------------------------------------------------------ */

/** @deprecated Use `CheckboxProps`. */
type CheckboxFieldProps = Omit<CheckboxProps, "label"> & { label: React.ReactNode }

/** @deprecated Use `Checkbox` with the same props (`label`, `description`, `error`). */
function CheckboxField(props: CheckboxFieldProps) {
  // wrapperClassName is always passed, so the alias renders the row even if label is empty.
  return <Checkbox {...props} wrapperClassName={props.wrapperClassName} />
}

/* ------------------------------------------------------------------ */
/* FormActions — right-aligned button row used at the end of forms       */
/* ------------------------------------------------------------------ */

function FormActions({ children, align = "end", className }: { children: React.ReactNode; align?: "start" | "end" | "between"; className?: string }) {
  return (
    <div
      data-slot="form-actions"
      className={cn(
        "flex flex-wrap items-center gap-2",
        align === "end" && "justify-end",
        align === "between" && "justify-between",
        className
      )}
    >
      {children}
    </div>
  )
}

export { TextField, PasswordField, TextareaField, CheckboxField, FormActions }
export type { TextFieldProps, TextareaFieldProps, CheckboxFieldProps }

"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { cn } from "@/lib/utils"
import { Icon } from "@/components/ui/icon-provider"
import * as React from "react"

/**
 * Base UI renders a hidden native <input> next to the visible control and gives it no name.
 * It is aria-hidden, but page checkers still list it as an unlabelled form control, so the
 * control's aria-label / aria-labelledby is mirrored onto it.
 */
function useNamedHiddenInput(inputRef: React.Ref<HTMLInputElement> | undefined, label?: string, labelledBy?: string) {
  return React.useCallback(
    (node: HTMLInputElement | null) => {
      if (node) {
        if (label) node.setAttribute("aria-label", label)
        else node.removeAttribute("aria-label")
        if (labelledBy) node.setAttribute("aria-labelledby", labelledBy)
        else node.removeAttribute("aria-labelledby")
      }
      if (typeof inputRef === "function") inputRef(node)
      else if (inputRef) (inputRef as React.RefObject<HTMLInputElement | null>).current = node
    },
    [inputRef, label, labelledBy]
  )
}

// Figma Appearance=Neutral: the filled box is the inverse surface (black in light, white in dark)
// with an inverse-coloured check instead of the brand fill. Hover and disabled stay as they are; an invalid box keeps its red rim.
const NEUTRAL_CHECKED =
  "data-checked:border-inverse data-checked:bg-inverse data-checked:text-text-inverse dark:data-checked:bg-inverse data-indeterminate:border-inverse data-indeterminate:bg-inverse data-indeterminate:text-text-inverse group-has-[:focus-visible]/field-label:data-checked:border-inverse"

// Figma Appearance=Brand: the filled box darkens on hover (brand-700) and pressed (brand-800), the same
// fixed tokens as the primary button, so the white mark keeps its contrast in both themes (7.0:1, 10.0:1).
// The border follows the fill unless the box is invalid (the red rim stays).
const BRAND_STATES =
  "hover:data-checked:bg-(--brand-700) hover:data-indeterminate:bg-(--brand-700) active:data-checked:bg-(--brand-800) active:data-indeterminate:bg-(--brand-800) hover:data-checked:not-aria-invalid:border-(color:--brand-700) hover:data-indeterminate:not-aria-invalid:border-(color:--brand-700) active:data-checked:not-aria-invalid:border-(color:--brand-800) active:data-indeterminate:not-aria-invalid:border-(color:--brand-800)"

type CheckboxControlProps = CheckboxPrimitive.Root.Props & {
  /** `brand` fills the checked box with the brand colour; `neutral` fills it with the inverse (black/white) surface. */
  appearance?: "brand" | "neutral"
}

type CheckboxFieldProps = {
  /** Visible label to the right of the box. Joined to the box with `htmlFor`; a click on it toggles the box. */
  label?: React.ReactNode
  /** A second line under the label in the tertiary colour. */
  description?: React.ReactNode
  /** Error message under the row. Sets `aria-invalid` and `aria-describedby` on the box and turns its rim red. */
  error?: React.ReactNode
  /** Class names for the row (or, with `error`, for the wrapper around the row and the message). */
  wrapperClassName?: string
}

type CheckboxProps = CheckboxControlProps & CheckboxFieldProps

/** The props that turn the bare box into a field row. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "description", "error", "wrapperClassName"] as const

/**
 * Checkbox. Without any of the field props (`label`, `description`, `error`,
 * `wrapperClassName`) it renders the bare box. With one of them it renders the
 * row: the box and its label (and description) in one `<label>`, so the whole
 * row is the click target; `error` adds the message under the row.
 */
function Checkbox(props: CheckboxProps) {
  const autoId = React.useId()
  if (!FIELD_PROPS.some((key) => key in props)) return <CheckboxControl {...props} />

  const { label, description, error, wrapperClassName, id: idProp, className, ...rest } = props
  const id = idProp ?? autoId
  // The message sits outside the label so it is not read as part of the box's name.
  const withMessage = "error" in props
  const row = (
    <label
      htmlFor={id}
      data-slot={withMessage ? undefined : "checkbox-field"}
      className={cn("group/checkbox-field flex cursor-pointer items-start gap-2 has-[[data-disabled]]:cursor-not-allowed", !withMessage && wrapperClassName)}
    >
      <CheckboxControl
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : undefined}
        className={cn("mt-0.5", className)}
        {...rest}
      />
      <span className="flex flex-col gap-0.5">
        {label && (
          <span className="text-sm text-text-secondary group-has-[[data-disabled]]/checkbox-field:opacity-40 [&_a]:font-medium [&_a]:text-text-link [&_a]:hover:underline">{label}</span>
        )}
        {description && <span className="text-xs text-text-tertiary group-has-[[data-disabled]]/checkbox-field:opacity-40">{description}</span>}
      </span>
    </label>
  )
  if (!withMessage) return row
  return (
    <div data-slot="checkbox-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {row}
      {error && (
        <p id={`${id}-error`} className="ps-6 text-xs text-text-error">
          {error}
        </p>
      )}
    </div>
  )
}

function CheckboxControl({
  className,
  inputRef,
  appearance = "brand",
  ...props
}: CheckboxControlProps) {
  const namedInputRef = useNamedHiddenInput(inputRef, props["aria-label"], props["aria-labelledby"])
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      data-appearance={appearance}
      inputRef={namedInputRef}
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-border-control bg-card transition-colors duration-fast ease-entrance outline-none hover:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary active:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary hover:not-data-checked:not-data-indeterminate:bg-bg-page active:not-data-checked:not-data-indeterminate:bg-bg-subtle after:absolute after:-inset-x-3 after:-inset-y-2 focus-ring data-disabled:cursor-not-allowed data-disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground data-indeterminate:border-primary data-indeterminate:bg-primary data-indeterminate:text-primary-foreground aria-invalid:data-checked:border-error aria-invalid:data-indeterminate:border-error",
        appearance === "brand" && BRAND_STATES,
        appearance === "neutral" && NEUTRAL_CHECKED,
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className={cn(
          "grid place-content-center text-current opacity-0 transition-opacity ease-entrance duration-fast data-checked:opacity-100 data-indeterminate:opacity-100 [&>svg]:size-3.5 [&>svg:last-child]:hidden data-indeterminate:[&>svg:first-child]:hidden data-indeterminate:[&>svg:last-child]:block",
          // The box fills instantly (see Root's data-checked:bg-primary above);
          // the check stroke draws in after via stroke-dashoffset. 23 is
          // lucide's CheckIcon path length (getTotalLength()), rounded up by 1
          // so the draw never over/under-shoots. Uncheck reverses fast with no
          // draw — transitioning offset (not toggling display) is what lets a
          // mid-draw uncheck reverse cleanly instead of jumping. The offset is
          // negative because lucide's path starts at the top-right end: the
          // tick draws from its short stroke up to the long one, like by hand.
          "[&_svg_path]:[stroke-dasharray:23] [&_svg_path]:[stroke-dashoffset:-23] [&_svg_path]:transition-[stroke-dashoffset] [&_svg_path]:duration-fast [&_svg_path]:ease-entrance data-checked:[&_svg_path]:[stroke-dashoffset:0] data-indeterminate:[&_svg_path]:[stroke-dashoffset:0] data-checked:[&_svg_path]:duration-slow"
        )}
      >
        {/* the roles checkboxCheck / checkboxIndeterminate (ui/icon-provider.tsx) draw Lucide heavier so the mark reads at 16 px: 3 on lucide's 24 grid for the check (about 1.75 px at 14 px), 4 for the minus, a short bar that looks thinner than the check at the same weight */}
        <Icon name="checkboxCheck" />
        <Icon name="checkboxIndeterminate" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
export type { CheckboxProps }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const textareaVariants = cva(
  "w-full min-w-0 resize-y rounded-md border border-input bg-card px-3 pt-3 pb-2 text-sm transition-colors duration-fast ease-entrance outline-none placeholder:text-muted-foreground hover:border-text-muted focus-ring aria-invalid:border-error aria-invalid:focus-ring-error [&[readonly]]:bg-bg-subtle disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40",
  {
    variants: {
      size: {
        // Density tokens (styles.css): compact 72/96/128, comfortable 80/112/144.
        sm: "min-h-(--textarea-sm)",
        default: "min-h-(--textarea-md)",
        lg: "min-h-(--textarea-lg) text-base",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

type TextareaControlProps = Omit<React.ComponentProps<"textarea">, "size"> &
  VariantProps<typeof textareaVariants> & {
    /** Show a "n/maxLength" character counter in the bottom-right corner. Requires maxLength. */
    showCount?: boolean
  }

type TextareaFieldProps = {
  /** Visible label. Joined to the control with `htmlFor`. */
  label?: React.ReactNode
  /** Adds the "(optional)" tag to the label. */
  optional?: boolean
  /** Hint below the field. Replaced by `error` while there is one. */
  helper?: React.ReactNode
  /** Error message below the field. Sets `aria-invalid` and `aria-describedby`. */
  error?: React.ReactNode
  /** Class names for the wrapper around label, field and message. */
  wrapperClassName?: string
}

type TextareaProps = TextareaControlProps & TextareaFieldProps

/** The props that turn the bare control into a field. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "optional", "helper", "error", "wrapperClassName"] as const

/**
 * Multi-line text field.
 *
 * Without any of the field props (`label`, `optional`, `helper`, `error`,
 * `wrapperClassName`) it renders the bare `<textarea>` (inside the box that
 * carries the counter). With one of them it renders the field: label row, the
 * control and the helper or error line, wired with `htmlFor`, `aria-invalid` and
 * `aria-describedby`.
 */
function Textarea(props: TextareaProps) {
  const autoId = React.useId()
  if (!FIELD_PROPS.some((key) => key in props)) return <TextareaControl {...props} />

  const { label, optional, helper, error, wrapperClassName, id: idProp, ...rest } = props
  const id = idProp ?? autoId
  // A disabled field dims its label and helper line with the control (Figma Field / Disabled).
  const dim = rest.disabled ? "opacity-40" : undefined
  return (
    <div data-slot="textarea-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {label && (
        <label htmlFor={id} className={cn("mb-1 text-sm font-medium text-foreground", dim)}>
          {label}
          {optional && <span className="ms-1 font-normal text-text-tertiary">(optional)</span>}
        </label>
      )}
      <TextareaControl
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : helper ? `${id}-helper` : undefined}
        {...rest}
      />
      {error ? (
        <p id={`${id}-error`} className="text-xs text-text-error">
          {error}
        </p>
      ) : (
        helper && (
          <p id={`${id}-helper`} className={cn("text-xs text-text-tertiary", dim)}>
            {helper}
          </p>
        )
      )}
    </div>
  )
}

function TextareaControl({
  className,
  size = "default",
  showCount,
  maxLength,
  value,
  defaultValue,
  onChange,
  ...props
}: TextareaControlProps) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue ?? "")
  const isControlled = value !== undefined
  const length = (isControlled ? value : uncontrolledValue)?.toString().length ?? 0
  const withCounter = showCount && maxLength !== undefined

  return (
    <div className="relative">
      <textarea
        data-slot="textarea"
        className={cn(textareaVariants({ size }), withCounter && "pb-6", className)}
        maxLength={maxLength}
        value={value}
        defaultValue={isControlled ? undefined : defaultValue}
        onChange={(event) => {
          if (!isControlled) setUncontrolledValue(event.target.value)
          onChange?.(event)
        }}
        {...props}
      />
      {withCounter && (
        <span className="pointer-events-none absolute right-3 bottom-2 text-xs text-text-tertiary tabular-nums">
          {length}/{maxLength}
        </span>
      )}
    </div>
  )
}

export { Textarea, textareaVariants }
export type { TextareaProps }

"use client"

import * as React from "react"
import { Input as InputPrimitive } from "@base-ui/react/input"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { InputGroup, InputGroupAddon } from "./input-group"
import { Tooltip, TooltipContent } from "./tooltip"

const inputVariants = cva(
  "w-full min-w-0 rounded-md border border-input bg-card text-sm transition-colors duration-fast ease-entrance outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground hover:border-text-muted focus-ring [&[readonly]]:bg-bg-subtle disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error",
  {
    variants: {
      size: {
        // Field heights are density tokens (styles.css): compact 32/36/40 — the
        // Button sm/md/lg — and data-density="comfortable" 36/44/52.
        sm: "h-(--field-sm) px-3 text-[13px]/[18px]",
        default: "h-(--field-md) px-3",
        lg: "h-(--field-lg) px-3",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

type InputControlProps = Omit<React.ComponentProps<"input">, "size"> & VariantProps<typeof inputVariants>

/**
 * The bare control: the `<input>` and its validation tooltip. Constraint
 * validation (`required`, `type="email"`, `pattern`, `minLength`…) answers in
 * the WunderUI tooltip instead of the browser's own bubble: on submit the first
 * invalid field is focused and shows the browser's message in a Tooltip, and
 * the message clears as soon as the user types or leaves the field.
 */
function InputControl({
  className,
  type,
  size = "default",
  ref,
  onInvalid,
  onInput,
  onBlur,
  ...props
}: InputControlProps) {
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const [message, setMessage] = React.useState<string | null>(null)
  const shown = React.useRef("")
  if (message) shown.current = message

  const setRefs = React.useCallback(
    (node: HTMLInputElement | null) => {
      inputRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) (ref as React.RefObject<HTMLInputElement | null>).current = node
    },
    [ref]
  )

  return (
    <>
      <InputPrimitive
        ref={setRefs}
        type={type}
        data-slot="input"
        className={cn(inputVariants({ size }), className)}
        onInvalid={(event: React.FormEvent<HTMLInputElement>) => {
          onInvalid?.(event)
          if (event.defaultPrevented) return
          event.preventDefault()
          const input = event.currentTarget
          // Every invalid field fires; only the first one in the form speaks.
          // Controls only: a <fieldset> around an invalid field matches :invalid too
          // and comes first in document order, which would silence every field in it.
          const first = input.form?.querySelector<HTMLElement>(":is(input, select, textarea):invalid")
          if (first && first !== input) return
          input.focus()
          setMessage(input.validationMessage)
        }}
        onInput={(event: React.InputEvent<HTMLInputElement>) => {
          onInput?.(event)
          if (message) setMessage(null)
        }}
        onBlur={(event: React.FocusEvent<HTMLInputElement>) => {
          onBlur?.(event)
          if (message) setMessage(null)
        }}
        {...props}
        aria-invalid={message ? true : props["aria-invalid"]}
      />
      <Tooltip open={!!message}>
        <TooltipContent anchor={inputRef} side="bottom" align="start" role="alert">
          {shown.current}
        </TooltipContent>
      </Tooltip>
    </>
  )
}

type InputFieldProps = {
  /** Visible label. Joined to the control with `htmlFor`. */
  label?: React.ReactNode
  /** A tag or a link on the label row, right-aligned (for example "Forgot password?"). */
  labelTrailing?: React.ReactNode
  /** Adds the "(optional)" tag to the label. */
  optional?: boolean
  /** Hint below the field. Replaced by `error` while there is one. */
  helper?: React.ReactNode
  /** Error message below the field. Sets `aria-invalid` and `aria-describedby`. */
  error?: React.ReactNode
  /** Content inside the field, before the text (icon, prefix). */
  leading?: React.ReactNode
  /** Content inside the field, after the text (icon, suffix, button). */
  trailing?: React.ReactNode
  /** Class names for the wrapper around label, field and message. */
  wrapperClassName?: string
  /** With `type="password"`: adds the button that shows or hides what was typed. */
  revealable?: boolean
}

type InputProps = InputControlProps & InputFieldProps

/** The props that turn the bare control into a field. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "labelTrailing", "optional", "helper", "error", "leading", "trailing", "wrapperClassName", "revealable"] as const

/**
 * Text input. Constraint validation (`required`, `type="email"`, `pattern`,
 * `minLength`…) answers in the WunderUI tooltip instead of the browser's own
 * bubble: on submit the first invalid field is focused and shows the browser's
 * message in a Tooltip, and the message clears as soon as the user types or
 * leaves the field.
 *
 * Without any of the field props (`label`, `labelTrailing`, `optional`, `helper`,
 * `error`, `leading`, `trailing`, `wrapperClassName`, `revealable`) it renders
 * the bare `<input>`. With one of them it renders the field: label row, the
 * control (inside an Input Group when there is leading or trailing content),
 * and the helper or error line, wired with `htmlFor`, `aria-invalid` and
 * `aria-describedby`. `revealable` on `type="password"` adds the show/hide button.
 */
function Input(props: InputProps) {
  const autoId = React.useId()
  const [visible, setVisible] = React.useState(false)
  if (!FIELD_PROPS.some((key) => key in props)) return <InputControl {...props} />

  const { label, labelTrailing, optional, helper, error, leading, trailing, wrapperClassName, revealable, size, id: idProp, className, ...rest } = props
  const id = idProp ?? autoId
  const reveal = !!revealable && rest.type === "password"
  const describedBy = error ? `${id}-error` : helper ? `${id}-helper` : undefined
  // A disabled field dims its label and helper line with the control (Figma Field / Disabled).
  const dim = rest.disabled ? "opacity-40" : undefined
  const end = reveal ? (
    <>
      {trailing}
      <button
        type="button"
        onClick={() => setVisible((v) => !v)}
        aria-label={visible ? "Hide password" : "Show password"}
        aria-pressed={visible}
        className="rounded-sm text-text-tertiary outline-none hover:text-foreground focus-ring"
      >
        {/* The icon shows the current state: dots hidden behind a
            crossed-out eye, plain text behind an open one. */}
        {visible ? <Icon name="show" className="size-4" /> : <Icon name="hide" className="size-4" />}
      </button>
    </>
  ) : (
    trailing
  )
  const control = (
    <InputControl
      id={id}
      size={size}
      aria-invalid={error ? true : undefined}
      aria-describedby={describedBy}
      className={className}
      {...rest}
      type={reveal && visible ? "text" : rest.type}
    />
  )
  return (
    <div data-slot="input-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {(label || labelTrailing) && (
        <div className="mb-1 flex items-center justify-between gap-2">
          {label && (
            <label htmlFor={id} className={cn("text-sm font-medium text-foreground", dim)}>
              {label}
              {optional && <span className="ms-1 font-normal text-text-tertiary">(optional)</span>}
            </label>
          )}
          {labelTrailing}
        </div>
      )}
      {leading || end ? (
        <InputGroup className={cn(size === "sm" && "[--ig-h:var(--field-sm)]", size === "lg" && "[--ig-h:var(--field-lg)]", error && "border-destructive")}>
          {leading && <InputGroupAddon>{leading}</InputGroupAddon>}
          {control}
          {end && <InputGroupAddon>{end}</InputGroupAddon>}
        </InputGroup>
      ) : (
        control
      )}
      {error ? (
        <p id={`${id}-error`} className="text-xs text-text-error">
          {error}
        </p>
      ) : (
        helper && (
          <p id={`${id}-helper`} className={cn("text-xs text-text-tertiary", dim)}>
            {helper}
          </p>
        )
      )}
    </div>
  )
}

